@startuml

class User {
  + ID : int
  + name : string
  + email : string
  + dateOfBirth : date
}

class Account {
  + accountNumber : int
}

class BusinessAccount extends Account {
  + companyName : string
  + monthlyFee : float
}

class PersonalAccount extends Account {
}

class Page {
  + name : string
  + numberOfVisits : int
}

class AdvertisementPage extends Page {
  + bounceRate : float
  + clickThroughRate : float
  + conversionRate : float
}

class Privilege {
}

User "1" -- "0..1" Account : owns
Account "1" -- "*" Page : administrates
PersonalAccount "1" -- "*" Privilege : grants
Privilege "*" -- "1" Page : applies to
PersonalAccount "1" -- "*" PersonalAccount : sends friend request
PersonalAccount "1" -- "*" PersonalAccount : receives friend request
BusinessAccount "1" -- "*" AdvertisementPage : creates

@enduml

